select 'romantic-10-red-roses-bouquet', 'Romantic 10 Red Roses Bouquet', 'Flowers', r.id, (select id from public.categories where slug = 'roses' limit 1), 549, 649, 4.9, 142, '90-Min Delivery', 'BESTSELLER', 'Speak the language of love with ten hand-picked velvet Dutch roses wrapped to perfection.', '10 freshly picked Dutch red roses wrapped in blush pink waterproof paper with delicate baby''s breath and a crimson satin ribbon.', '/products/flowers/red-roses-bouquet.jpg', array['/products/flowers/red-roses-bouquet.jpg','/products/flowers/red-roses-bouquet-macro.jpg','/products/flowers/red-roses-bouquet-ribbon.jpg','/products/flowers/red-roses-bouquet-crown.jpg']::text[], false, null, '{"stemCount":"10 Stems + Fillers","flowers":["10 Fresh Dutch Red Roses"],"fillers":"White Gypsophila (Baby''s Breath) & Asparagus Greens","packaging":"Two-layer Premium Blush Pink Waterproof Matte Wrap","ribbon":"Crimson Red Silk Satin Ribbon","height":"Approx 12 - 14 inches"}'::jsonb, array['Trim 1-2 cm off the bottom of each stem at a 45-degree angle before putting them in water.','Place in a clean vase filled with fresh, cool water and dissolve flower food if provided.','Keep the bouquet away from direct sunlight, drafts, ceiling fans, and ripening fruit.','Change the vase water every 2 days to maintain petal crispness and longevity.']::text[], array['Delivered in protective, water-fed hydration pouches so blooms stay farm-fresh during transit.','Hand-arranged by experienced local florists right before dispatch.','Includes a complimentary personalized message card for your special note.']::text[], '[{"id":"rev-1","author":"Priya Sengupta","city":"South Kolkata","rating":5,"date":"Yesterday","comment":"Ordered for my anniversary. The roses arrived in 75 minutes and were super fresh with morning dew droplets!"},{"id":"rev-2","author":"Rahul Verma","city":"Salt Lake","rating":5,"date":"3 days ago","comment":"Packaging was premium Korean paper, just like the photos. My fiance loved it completely."},{"id":"rev-3","author":"Ananya Roy","city":"New Town","rating":4.8,"date":"1 week ago","comment":"Smells divine and lasted almost 6 days with regular water changes. Highly recommend MS Flowers!"}]'::jsonb, true, 25, 5, true
