select 'blooming-symphony-gift-bouquet', 'Blooming Symphony Gift Bouquet', 'Flowers', r.id, (select id from public.categories where slug = 'lilies' limit 1), 899, 1049, 4.8, 88, 'Same Day Delivery', 'POPULAR', 'A melodious duet of fragrant Asiatic lilies and gentle pastel pink carnations for unforgettable moments.', 'Fragrant white oriental lilies paired with soft pink carnations wrapped in rustic luxury craft paper with imported twine ribbon.', '/products/flowers/white-lilies-carnations.jpg', array['/products/flowers/white-lilies-carnations.jpg','/products/flowers/white-lilies-carnations-macro.jpg','/products/flowers/white-lilies-carnations-ribbon.jpg','/products/flowers/white-lilies-carnations-top.jpg']::text[], false, null, '{"stemCount":"14 Stems Total","flowers":["3 White Asiatic Lily Stems (6-8 blooms)","8 Soft Pink Carnations"],"fillers":"White Waxflowers & Green Ruscus Foliage","packaging":"Eco-friendly Dual Kraft & Japanese Vellum Paper","ribbon":"Natural Jute Twine with Pastel Pink Grosgrain Ribbon","height":"Approx 15 - 18 inches"}'::jsonb, array['Remove pollen anthers carefully from lilies as they open to prevent petal staining.','Cut stems diagonally by 1 inch and remove any leaves submerged below the water level.','Mist petals lightly with clean water once a day in dry or air-conditioned rooms.','Keep away from direct heat sources to extend bloom life up to 8 days.']::text[], array['Lilies may arrive in bud form to protect them during transit and ensure maximum blooming life at home.','Hand-crafted by master florists within 2 hours of dispatch.','Complimentary greeting card included with your custom heartfelt message.']::text[], '[{"id":"rev-4","author":"Devika Mukherjee","city":"Ballygunge","rating":5,"date":"2 days ago","comment":"The lilies bloomed completely by the next morning and the fragrance filled the entire living room!"},{"id":"rev-5","author":"Sourav Paul","city":"Howrah","rating":5,"date":"5 days ago","comment":"IGP style luxury presentation at a much friendlier price. Delivery was punctual."}]'::jsonb, false, 25, 5, true
