select 'royal-purple-orchids-in-glass-vase', 'Royal Purple Orchids in Glass Vase', 'Flowers', r.id, (select id from public.categories where slug = 'orchids' limit 1), 999, 1199, 4.9, 76, 'Same Day Delivery', 'EXOTIC', 'Exotic purple dendrobium orchids in a crystal glass vase that exudes opulence and modern grace.', 'Exotic purple dendrobium orchids gracefully arranged with lush green foliage in an elegant reusable clear glass cylinder vase.', '/products/flowers/purple-orchids-vase.jpg', array['/products/flowers/purple-orchids-vase.jpg','/products/flowers/purple-orchids-vase-macro.jpg','/products/flowers/purple-orchids-vase-vase.jpg','/products/flowers/purple-orchids-vase.jpg']::text[], false, null, '{"stemCount":"8 Long Orchid Sprays","flowers":["8 Purple Dendrobium Orchid Stems (approx 35+ blooms)"],"fillers":"Lush Palm Greens & Asparagus Fern","packaging":"Clear Cylindrical Heavy Glass Vase (Free)","ribbon":"Deep Violet Organza Ribbon","height":"Approx 16 - 18 inches"}'::jsonb, array['Orchids love indirect daylight; avoid placing them in dark corners or direct sun.','Replenish vase water every other day, ensuring stems remain submerged 3-4 inches.','Keep stems clean by gently wiping vase glass if water appears cloudy.']::text[], array['Arrives fully assembled inside the protective glass vase.','Securely packaged in a shock-absorbing thermocol cradle to prevent breakage.']::text[], '[{"id":"rev-6","author":"Sneha Ghosh","city":"Park Street","rating":5,"date":"4 days ago","comment":"The glass vase arrangement is stunning! It looks so premium on our dining table."}]'::jsonb, false, 25, 5, true
