select 'luxury-black-box-20-red-roses', 'MS Luxury Black Box of 20 Red Roses', 'Flowers', r.id, (select id from public.categories where slug = 'boxes' limit 1), 1299, 1549, 5, 115, '90-Min Delivery', 'LUXURY', 'The pinnacle of floral luxury: 20 velvety red roses nestled in a gold-embossed matte black hatbox.', '20 premium deep velvet red roses hand-arranged in a signature matte black cylindrical box with silk ribbon.', '/products/flowers/luxury-roses-box.jpg', array['/products/flowers/luxury-roses-box.jpg','/products/flowers/luxury-roses-box-macro.jpg','/products/flowers/luxury-roses-box-box.jpg','/products/flowers/luxury-roses-box.jpg']::text[], false, null, '{"stemCount":"20 Roses","flowers":["20 Grade-A Taj Mahal Red Roses"],"fillers":"Dense Oasis Floral Foam with hydration nutrition","packaging":"Rigid Cylindrical Matte Black Keepsake Box with Gold Foil Logo","ribbon":"Double-face Gold Trimmed Black Satin Ribbon","height":"Approx 9 inches (Box Diameter 8 inches)"}'::jsonb, array['Flowers are set in specialized floral foam that retains water.','Add half a cup of water directly to the center of the box every morning.','Do not pull flowers out of the foam.']::text[], array['Hand-carried in a luxury MS Flowers branded carry bag.','Available with 90-minute express delivery across Kolkata.']::text[], '[{"id":"rev-7","author":"Arindam Bhattacharya","city":"Alipore","rating":5,"date":"Yesterday","comment":"Unboxing experience was 10/10. Looked even better than five-star hotel floral arrangements."}]'::jsonb, true, 25, 5, true
